const config = $('Pipeline Config').first().json;
function cleanJsonText(raw) {
  let text = raw;

  if (typeof raw === 'object' && raw !== null) {
    if (raw.parts?.[0]?.text) text = raw.parts[0].text;
    else if (raw.output?.[0]?.content?.[0]?.text) text = raw.output[0].content[0].text;
    else text = JSON.stringify(raw);
  }

  return String(text || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function safeParse(raw) {
  if (raw == null || raw === '') return null;

  try {
    return JSON.parse(cleanJsonText(raw));
  } catch (error) {
    try {
      return JSON.parse(cleanJsonText(raw).replace(/\\"/g, '"'));
    } catch (repairError) {
      return {
        _parse_error: repairError.message,
        _raw: cleanJsonText(raw).slice(0, 4000)
      };
    }
  }
}

function compactAdapter(adapter) {
  return {
    source_fidelity: adapter?.source_fidelity ?? null,
    visual_anchor: adapter?.visual_anchor ?? null,
    adapted_concept: adapter?.adapted_concept ?? null,
    new_hook: adapter?.new_hook ?? null,
    new_script_15s: adapter?.new_script_15s ?? adapter?.new_script ?? null,
    shot_plan_15s: adapter?.shot_plan_15s ?? adapter?.scene_structure ?? [],
    production_notes: adapter?.production_notes ?? [],
    do_not_include: adapter?.do_not_include ?? []
  };
}

function compactOriginal(original) {
  const host = Array.isArray(original?.people) ? original.people[0] : null;
  return {
    format: original?.format ?? null,
    structure: original?.structure ?? null,
    core_idea: original?.core_idea ?? null,
    hook_visual: original?.hook?.visual ?? null,
    hook_verbal: original?.hook?.verbal ?? null,
    style: original?.style ?? null,
    host: host ? {
      appearance: host.appearance ?? null,
      outfit: host.outfit ?? null,
      key_action: host.key_action ?? null
    } : null,
    locations: Array.isArray(original?.segments) ? [...new Set(original.segments.map(s => s.location).filter(Boolean))].slice(0, 3) : []
  };
}

function compactDna(dna) {
  return {
    video_duration_sec: dna?.video_duration_sec ?? null,
    main_video_language: dna?.main_video_language ?? null,
    primary_format: dna?.primary_format ?? null,
    core_mechanic: dna?.core_mechanic ?? null,
    hook_type: dna?.hook_type ?? null,
    hook_text: dna?.hook_text ?? null,
    primary_angle: dna?.primary_angle ?? null,
    dominant_emotion: dna?.dominant_emotion ?? null,
    emotional_arc: dna?.emotional_arc ?? [],
    viral_mechanics: dna?.viral_mechanics ?? [],
    psychological_triggers: dna?.psychological_triggers ?? [],
    pattern: dna?.pattern ?? null,
    script_summary: dna?.script_summary ?? null,
    ai_video_generation_score: dna?.ai_video_generation_score ?? null,
    product_fit_score: dna?.product_fit?.score ?? null
  };
}

return items.map(item => {
  const original = safeParse(item.json['Original json file']);
  const dna = safeParse(item.json.DNA_Extractor);
  const adapter = safeParse(item.json.Adapter);

  item.json.prompt_generator_input = {
    row: {
      shortcode: item.json.shortcode ?? item.json.id ?? null,
      postPage: item.json.url ?? item.json.postPage ?? null,
      score: item.json.score ?? null
    },
    original_anchor: compactOriginal(original),
    creative_dna: compactDna(dna),
    adaptation: compactAdapter(adapter),
    source_fidelity_policy: {
      preserve_visual_anchor: 'Use adaptation.visual_anchor first. If missing, use original_anchor. Do not invent a different speaker, location, or format.',
      preserve_topic_anchor: 'If a topic relevant to the configured product exists in the source or adaptation, it must appear in the generated dialogue.',
      no_text_rendering: 'Do not ask the video model to render readable text, captions, title cards, labels, book pages, screenshots, app screens, or UI. Subtitles and branded outro are added after generation.'
    },
    parse_warnings: {
      original: original?._parse_error ?? null,
      dna: dna?._parse_error ?? null,
      adapter: adapter?._parse_error ?? null
    },
    output_requirements: {
      duration_sec: config.scoring.target_video_duration_sec,
      aspect_ratio: config.generation.aspect_ratio,
      target_model: 'kling',
      seedance_max_chars: 5000,
      kling_max_chars: 2500,
      spoken_brand_policy: `Do not say ${config.product.name} in dialogue. Use a generic product reference instead.`,
      no_interface_policy: 'Do not show app UI, interfaces, screens, phone/laptop/tablet screen close-ups, waveform animations, screenshots, buttons, menus, dashboards, text messages, or readable digital surfaces.',
      no_text_policy: 'Do not include overlays, captions, subtitles, lower-thirds, title cards, labels, floating text, on-screen text, typography, readable books/pages, or any text rendered in the video.',
      branded_outro_policy: 'A separate branded outro and subtitles will be added later. Do not include logo animation, captions, overlays, or a spoken brand tagline.',
      visual_style: 'realistic vertical TikTok ad, casual UGC realism, source-matched setting and camera, fast cuts, natural phone-video imperfections'
    }
  };

  return item;
});

const productName = $('Pipeline Config').first().json.product.name;
const escapedProductName = String(productName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const productNamePattern = new RegExp(escapedProductName, 'i');
function cleanJsonText(raw) {
  return String(raw || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

const interfacePattern = /\b(ui|interface|app screen|phone screen|screen close|close-up on phone|close up on phone|laptop screen|tablet screen|waveform|screenshot|button|buttons|menu|menus|dashboard|text message|text messages|readable screen|digital surface)\b/i;
const textPattern = /\b(overlay|overlays|caption|captions|subtitle|subtitles|lower-third|lower third|title card|label|labels|floating text|on-screen text|onscreen text|kinetic typography|typography|text rendered|readable text|readable page|book page close-up|close-up of a book page)\b/i;

return items.map(item => {
  const raw = item.json.output?.[0]?.content?.[0]?.text
    || item.json.text
    || item.json.message?.content
    || JSON.stringify(item.json);

  try {
    const parsed = JSON.parse(cleanJsonText(raw));
    const klingPrompt = parsed?.kling?.prompt ?? '';
    const klingLen = klingPrompt.length;
    const dialogue = JSON.stringify(parsed?.creative_brief?.dialogue ?? []);
    const hasSeedance = parsed?.seedance !== undefined;
    const hasOverlayText = parsed?.creative_brief?.overlay_text !== undefined;
    const hasInterface = interfacePattern.test(klingPrompt);
    const hasText = textPattern.test(klingPrompt);
    const valid = klingLen > 0
      && klingLen <= 2500
      && !productNamePattern.test(dialogue)
      && !hasSeedance
      && !hasOverlayText
      && !hasInterface
      && !hasText;

    item.json.final_prompt_kling = JSON.stringify(parsed);
    item.json.kling_prompt_status = valid ? 'kling_prompt_generated' : 'kling_prompt_needs_review';
    item.json.kling_prompt_validation_note = `kling=${klingLen}, has_seedance=${hasSeedance}, has_overlay_text=${hasOverlayText}, has_interface=${hasInterface}, has_text_or_overlay=${hasText}`;
  } catch (error) {
    item.json.final_prompt_kling = raw;
    item.json.kling_prompt_status = 'kling_prompt_parse_error';
    item.json.kling_prompt_validation_note = error.message;
  }

  return item;
});

return [{
  json: {
    product: {
      name: "Speechify",
      description: "An app that turns books, PDFs, articles, emails, and documents into audio using AI voices.",
      audiences: ["people with ADHD or focus challenges", "students", "professionals", "busy readers"],
      value_props: ["save time", "listen instead of read", "consume more content", "learn while multitasking"],
      target_markets: ["US", "CA", "GB", "AU"]
    },
    scoring: {
      allowed_languages: ["en"],
      max_source_duration_sec: 60,
      target_video_duration_sec: 15,
      min_product_fit_score: 0.60,
      min_ai_video_generation_score: 0.60,
      reject_local_or_cultural_concepts: true
    },
    generation: {
      aspect_ratio: "9:16",
      seedance_model: "bytedance/seedance-2",
      kling_model: "kling-3.0/video"
    }
  }
}];
